const b=$json.body??$json;
const required=['organization_id','agent_id','idempotency_key','channel','event_type','input'];
const missing=required.filter(k=>b[k]===undefined||b[k]===null||b[k]==='');
if(missing.length) throw new Error('Missing required tenant fields: '+missing.join(', '));
const allowed=['whatsapp','email','web_chat','telegram','voice','internal'];
if(!allowed.includes(b.channel)) throw new Error('Unsupported channel');
const input=b.input||{};
const customerKey=String(b.customer_id||input.customer_key||input.email||input.phone||input.customer?.email||input.customer?.phone||'').trim();
if(!customerKey) throw new Error('customer_id or customer identifier required');
return [{json:{organization_id:String(b.organization_id),organization_key:b.organization_key||input.organization_key||null,agent_id:String(b.agent_id),conversation_id:b.conversation_id||null,customer_id:b.customer_id||null,customer_key:customerKey,idempotency_key:String(b.idempotency_key),channel:b.channel,event_type:b.event_type,external_thread_key:b.external_thread_key||input.external_thread_key||null,input,received_at:new Date().toISOString(),workflow_key:'ai_sales_qualification_v2'}}];

const ctx=$('Build Provider Request').first().json;
let raw=String($json.output_text||'').replace(/^```json\s*/i,'').replace(/```$/,'').trim();
let q; try{q=JSON.parse(raw)}catch(e){throw new Error('Invalid AI JSON: '+raw.slice(0,300))}
const statuses=['hot','warm','cold','disqualified'];
const stages=['new','qualified','contacted','nurturing','appointment','disqualified'];
q.qualification_status=statuses.includes(q.qualification_status)?q.qualification_status:'warm';
q.score=Math.max(0,Math.min(100,Math.round(Number(q.score)||0)));
q.stage=stages.includes(q.stage)?q.stage:(q.score>=70?'qualified':q.score>=35?'nurturing':'new');
q.appointment_requested=Boolean(q.appointment_requested);
q.handoff_required=Boolean(q.handoff_required);
q.meaningful_conversation=Boolean(q.meaningful_conversation);
q.campaign_only=Boolean(q.campaign_only);
q.specific_interest=String(q.specific_interest||'').trim()||null;
q.property_interest=String(q.property_interest||'').trim()||null;
q.objections=Array.isArray(q.objections)?q.objections:[];
q.missing_fields=Array.isArray(q.missing_fields)?q.missing_fields:[];
q.memory_facts=Array.isArray(q.memory_facts)?q.memory_facts:[];
return [{json:{...ctx,qualification:q,provider_usage:$json.usage||{},provider_response_id:$json.response_id||null,provider:$json.provider,model:$json.model}}];

const r=$json;
const actions=[];
if(r.handoff_required) actions.push({type:'handoff',payload:r.handoff});
if(r.appointment_required) actions.push({type:'appointment',payload:r.appointment});
if(r.follow_up_required) actions.push({type:'follow_up',payload:r.follow_up});
if(r.reply_action) actions.push({type:'reply',payload:r.reply_action});
return [{json:{...r,actions}}];
